// Fetches current weather for every seat of one assembly and writes it to
// that assembly's weatherData.json, which its page reads at load time.
// Same pattern as ../../mangalaExpress/scrapeWeather.js — a snapshot
// generated by hand-running this script, not a live per-visitor API call.
// The page's "Get current weather" button does the same fetch in the browser.
//
// Run from the assemblyWeather folder, naming the state's folder:
//   node shared/scrapeWeather.js keralaAssembly        (140 seats, ~2.5 min)
//   node shared/scrapeWeather.js tamilNaduAssembly     (234 seats, ~4.5 min)
//   node shared/scrapeWeather.js chhattisgarhAssembly  (90 seats, ~1.7 min)
//   node shared/scrapeWeather.js jammuKashmirAssembly  (90 seats, ~1.7 min)
//   node shared/scrapeWeather.js telanganaAssembly  (119 seats, ~2.2 min)
//   node shared/scrapeWeather.js andhraPradeshAssembly  (175 seats, ~3.2 min)
//   node shared/scrapeWeather.js karnatakaAssembly  (224 seats, ~4.2 min)
//   node shared/scrapeWeather.js maharashtraAssembly  (288 seats, ~5.3 min)
//   node shared/scrapeWeather.js gujaratAssembly  (182 seats, ~3.4 min)
//   node shared/scrapeWeather.js himachalPradeshAssembly  (68 seats, ~1.3 min)
//   node shared/scrapeWeather.js punjabAssembly  (117 seats, ~2.2 min)
//   node shared/scrapeWeather.js uttarakhandAssembly  (70 seats, ~1.3 min)
//
// Keyed by `no` — the seat's official constituency number, unique and stable.

const fs = require("fs");
const path = require("path");

// Same free-tier key every other scrapeWeather.js in this app already
// ships to the browser — reusing it here doesn't expose anything new.
const API_KEY = "39a9a737b07b4b703e3d1cd1e231eedc";
const DELAY_MS = 1100; // keeps us under OpenWeather's free-tier 60-calls/minute limit

const FOLDER = process.argv[2];
if (!FOLDER || !fs.existsSync(path.join(__dirname, "..", FOLDER, "seats.json"))) {
  console.error("Usage: node shared/scrapeWeather.js <stateFolder>   e.g. keralaAssembly");
  process.exit(1);
}
const SEATS_PATH = path.join(__dirname, "..", FOLDER, "seats.json");
const OUTPUT_PATH = path.join(__dirname, "..", FOLDER, "weatherData.json");

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function fetchWeather(seat) {
  const url =
    `https://api.openweathermap.org/data/2.5/weather` +
    `?lat=${seat.lat}&lon=${seat.lon}&units=metric&appid=${API_KEY}`;

  const response = await fetch(url);
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.message || `Request failed (${response.status})`);
  }

  return {
    temp: data.main.temp,
    description: data.weather[0] ? data.weather[0].description : "",
    timezone: data.timezone,
    sunrise: data.sys.sunrise,
    sunset: data.sys.sunset,
    dayLengthSeconds: data.sys.sunset - data.sys.sunrise,
    readingAt: data.dt, // when OpenWeather took this reading
  };
}

async function main() {
  const seats = JSON.parse(fs.readFileSync(SEATS_PATH, "utf8"));
  const existing = fs.existsSync(OUTPUT_PATH)
    ? JSON.parse(fs.readFileSync(OUTPUT_PATH, "utf8"))
    : { generatedAt: null, byNo: {} };

  const byNo = { ...existing.byNo };
  let failures = 0;

  for (const seat of seats) {
    process.stdout.write(`#${seat.no} ${seat.constituency}, ${seat.district}... `);
    try {
      byNo[seat.no] = await fetchWeather(seat);
      console.log(`ok, ${byNo[seat.no].temp.toFixed(1)}°C`);
    } catch (err) {
      // Keep whatever this seat had from the last successful scrape
      // rather than blanking its row out over one flaky request.
      failures += 1;
      console.log(`FAILED (${err.message}) — keeping previous data`);
    }
    await sleep(DELAY_MS);
  }

  const output = { generatedAt: Math.floor(Date.now() / 1000), byNo };
  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(output, null, 2) + "\n");
  console.log(`\nWrote ${Object.keys(byNo).length} entries to ${OUTPUT_PATH}` +
    (failures ? ` (${failures} failed this run, old data kept for those)` : ""));
}

main();
